mapper.select:
SELECT b.*, d.device_name, d.device_no, u.real_name AS user_name, a.expected_return_time FROM borrow_record b LEFT JOIN device d ON b.device_id = d.id LEFT JOIN `user` u ON b.user_id = u.id LEFT JOIN borrow_apply a ON b.apply_id = a.id
AND b.status = #{status} AND b.user_id = #{userId}
ORDER BY b.borrow_time DESC

mapper.update:
UPDATE borrow_record
return_time = #{returnTime}, status = #{status}, remark = #{remark},
WHERE id = #{id}
